function onCell(r,c){if(state.phase!=='build')return;let occupying=state.units.find(u=>u.side==='player'&&!u.dead&&u.row===r&&u.col===c);if(state.selected){let source=state.selected.kind==='bench'?state.bench.find(u=>u.id===state.selected.id):state.units.find(u=>u.id===state.selected.id);if(!source)return;if(r>=2){toast('Deploy only in your half of the field.');return}if(occupying&&occupying.id!==source.id){if(state.selected.kind==='board'){let old={row:source.row,col:source.col};source.row=occupying.row;source.col=occupying.col;occupying.row=old.row;occupying.col=old.col}else{toast('That tile is occupied.');return}}else if(state.selected.kind==='bench'){if(state.units.filter(u=>u.side==='player').length>=state.level){toast('Command limit reached. Upgrade your command level.');return}state.bench=state.bench.filter(u=>u.id!==source.id);source.row=r;source.col=c;source.side='player';state.units.push(source)}else{source.row=r;source.col=c}state.selected=null;render();return}
if(occupying){inspect(occupying);render()} }
function onBench(i){if(state.phase!=='build')return;let u=state.bench[i];if(state.selected){let source=state.selected.kind==='board'?state.units.find(x=>x.id===state.selected.id):state.bench.find(x=>x.id===state.selected.id);if(!source)return;if(!u){if(state.selected.kind==='board'){state.units=state.units.filter(x=>x.id!==source.id);source.side='player';state.bench.push(source)}state.selected=null;render();return}if(source.id!==u.id&&state.selected.kind==='bench'){let a=state.bench.indexOf(source),b=state.bench.indexOf(u);[state.bench[a],state.bench[b]]=[state.bench[b],state.bench[a]]}else if(source.id!==u.id&&state.selected.kind==='board'){if(state.bench.length>=5){toast('Reserve bay is full.');return}state.units=state.units.filter(x=>x.id!==source.id);source.side='player';state.bench.push(source);u.row=source.row;u.col=source.col;state.units.push(u);state.bench=state.bench.filter(x=>x.id!==u.id)}state.selected=null;render();return}if(u){state.selected={kind:'bench',id:u.id};inspect(u);render()}}
function randomTemplate(){return units[Math.floor(Math.random()*units.length)]}
function refillShop(){state.shop=Array.from({length:4},()=>({id:randomTemplate().id,sold:false}))}
function buy(i){if(state.phase!=='build')return;let card=state.shop[i],t=units.find(x=>x.id===card.id);if(!card||card.sold)return;if(state.gold<t.cost){toast('Not enough scrap.');return}let duplicate=[...state.units.filter(u=>u.side==='player'),...state.bench].find(u=>u.template===t.id&&u.star===1);if(!duplicate&&state.bench.length>=5){toast('Reserve bay full.');return}state.gold-=t.cost;card.sold=true;if(duplicate){duplicate.star=2;duplicate.maxHp=t.hp*1.65;duplicate.hp=duplicate.maxHp;duplicate.atk=t.atk*1.55;duplicate.armor=t.armor*1.45;toast(`${t.name} upgraded to ★★!`)}else{let u=makeUnit(t,'player');state.bench.push(u);toast(`${t.name} recruited.`)}state.selected=null;render()}
function sellSelected(){if(!state.selected||state.phase!=='build')return;let u=state.selected.kind==='bench'?state.bench.find(x=>x.id===state.selected.id):state.units.find(x=>x.id===state.selected.id);if(!u)return;let t=template(u);state.gold+=Math.max(1,Math.floor(t.cost*(u.star===2?1.5:0.65)));state.bench=state.bench.filter(x=>x.id!==u.id);state.units=state.units.filter(x=>x.id!==u.id);state.selected=null;toast(`${t.name} sold for scrap.`);render()}
function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function reroll(){if(state.phase!=='build'||state.gold<2)return;state.gold-=2;refillShop();render();toast('Supply depot refreshed.')}
function toggleLock(){state.locked=!state.locked;$('lockBtn').classList.toggle('active',state.locked);$('lockBtn').textContent=state.locked?'▣':'⌑';toast(state.locked?'Shop locked for next round.':'Shop will refresh next round.')}
function initialize(){let start=[['wolf',0,1],['shield',1,1],['gunner',0,2]];start.forEach(([id,r,c])=>{let u=makeUnit(units.find(x=>x.id===id));u.row=r;u.col=c;state.units.push(u)});refillShop();for(let i=0;i<4;i++)$('roundProgress').innerHTML+=`<span class="pip ${i===0?'current':''}"></span>`;render()}
