function beginBattle(){if(state.phase!=='build')return;state.selected=null;state.phase='combat';state.units=state.units.filter(u=>u.side==='player');state.units.forEach(u=>{u.hp=u.maxHp;u.dead=false});state.units.push(...enemySquad());$('battleBtn').disabled=true;$('battleBtn').textContent='COMBAT ENGAGED';$('boardHint').textContent='Auto-battle in progress — your Zoids are fighting!';render();state.combatTimer=setInterval(combatStep,480);}
function distance(a,b){return Math.abs(a.row-b.row)+Math.abs(a.col-b.col)}
function combatStep(){if(state.phase!=='combat')return;let alive=state.units.filter(u=>!u.dead);let players=alive.filter(u=>u.side==='player'),enemies=alive.filter(u=>u.side==='enemy');if(!players.length||!enemies.length){finishBattle(!!players.length);return}
let occupied=new Set(alive.map(u=>`${u.row},${u.col}`));for(let u of alive){if(u.dead)continue;let foes=alive.filter(x=>!x.dead&&x.side!==u.side);if(!foes.length)continue;foes.sort((a,b)=>distance(u,a)-distance(u,b));let target=foes[0];if(distance(u,target)<=u.range){target.hp-=Math.max(4,u.atk-target.armor*.55)*(u.side==='player'&&synergyCount('Canine')>=2?1.04:1);let sourceEl=document.querySelector(`.mech[data-id="${u.id}"]`),targetEl=document.querySelector(`.mech[data-id="${target.id}"]`);if(sourceEl){sourceEl.classList.remove('attacking');void sourceEl.offsetWidth;sourceEl.classList.add('attacking')}if(sourceEl&&targetEl)shoot(sourceEl,targetEl);if(target.hp<=0){target.dead=true;if(targetEl)targetEl.classList.add('falling')}}else{let oldKey=`${u.row},${u.col}`;occupied.delete(oldKey);let opts=[[u.row+Math.sign(target.row-u.row),u.col],[u.row,u.col+Math.sign(target.col-u.col)],[u.row-Math.sign(target.row-u.row),u.col],[u.row,u.col-Math.sign(target.col-u.col)]];let next=opts.find(([r,c])=>r>=0&&r<4&&c>=0&&c<4&&!occupied.has(`${r},${c}`));if(next){u.row=next[0];u.col=next[1];occupied.add(`${u.row},${u.col}`)}else occupied.add(oldKey)}}render();}
function shoot(a,b){const arena=document.querySelector('.arena'),rect=arena.getBoundingClientRect(),ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();let p=document.createElement('i');p.className='projectile';p.style.left=`${ar.left+ar.width/2-rect.left}px`;p.style.top=`${ar.top+ar.height/2-rect.top}px`;arena.appendChild(p);requestAnimationFrame(()=>{p.style.left=`${br.left+br.width/2-rect.left}px`;p.style.top=`${br.top+br.height/2-rect.top}px`;p.style.opacity='0'});setTimeout(()=>p.remove(),300)}
function synergyCount(type){return state.units.filter(u=>u.side==='player'&&!u.dead&&template(u).type===type).length}
function finishBattle(win){clearInterval(state.combatTimer);state.phase='result';let enemyAlive=state.units.filter(u=>u.side==='enemy'&&!u.dead).length;let overlay=$('battleOverlay');overlay.classList.add('show');$('resultTitle').textContent=win?'VICTORY':'DEFEAT';$('resultTitle').style.color=win?'var(--lime)':'var(--red)';$('resultIcon').textContent=win?'✦':'✕';if(win){state.gold+=3+Math.floor(state.round/3);state.xp+=2;if(state.xp>=4){state.xp-=4;state.level=Math.min(6,state.level+1);state.gold+=1}$('resultText').textContent=`FIELD SECURED · +${3+Math.floor(state.round/3)} SCRAP · +2 COMMAND XP`}else{state.lives--;state.gold+=2;$('resultText').textContent=`SQUAD OVERWHELMED · ${enemyAlive} HOSTILES REMAIN · +2 SCRAP`};if(state.lives<=0){$('resultTitle').textContent='CAMPAIGN LOST';$('resultTitle').style.color='var(--red)';$('continueBtn').textContent='RESTART CAMPAIGN →';$('resultText').textContent='CORE INTEGRITY DEPLETED · RETRY THE FRONTIER'}$('boardHint').textContent=win?'Victory! Your squad earned rewards.':'Your Zoids were defeated. Regroup and try again.';render()}
