$('rerollBtn').addEventListener('click',reroll);$('lockBtn').addEventListener('click',toggleLock);$('battleBtn').addEventListener('click',beginBattle);$('continueBtn').addEventListener('click',continueCampaign);$('helpBtn').addEventListener('click',()=>$('helpModal').classList.add('show'));$('closeHelp').addEventListener('click',()=>$('helpModal').classList.remove('show'));$('helpModal').addEventListener('click',e=>{if(e.target===$('helpModal'))$('helpModal').classList.remove('show')});
